head.script:
// 호출메뉴ID를 식별하기 위한 함수사용
// 상장관련공통함수
// 세션정보를 얻기위한 함수사용

scwin.fn_GetPar, scwin.fn_SetPar;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        $c.libRoundPanel.PanelToGroupBox(panel_Top);
        txb_IsurCd.setValue($c.stf.getQuery(frame.srcUrl, "ISUR_CD"));
        txb_IsurNm.setValue($c.stf.getQuery(frame.srcUrl, "COM_NM"));
        await scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF37704.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name img_Excel_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_Excel_onclick = async function() {
    try {
        if (dts_List.getRowCount() > 0) {
            // 엑셀 로그
            $c.stf.doLogSave("ULDSTF37704.xml", SCREN_PROCS_TP_CD_07);
            $c.data.downloadGridViewExcel(grd_List, {fileName: $c.lc.fn_getSecuGrpNm("ST") + "괸리종목지정내역", type: "8"});
        } else {
            await $c.win.alert(NO_EXCEL_DATA);
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF37704.img_Excel_onclick" });
    }
};

/**
 * @method
 * @name img_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_Search_onclick = async function() {
    try {
        if (txb_IsurCd.getValue() !== "") {
            await scwin.search();
        } else {
            await $c.win.alert($c.stf.getMessageParam("MSG-0013", ""));
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF37704.img_Search_onclick" });
    }
};

/**
 * @method
 * @name btn_IsuCdSearch_onclick
 * @description btn_IsuCdSearch 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_IsuCdSearch_onclick = function() {
    try {
        scwin.fn_GetPar = scwin.getParIsur;
        scwin.fn_SetPar = scwin.setParIsur;
        $c.lc.fn_PopFindCorpChrgSW("ST", "2");

        // fn_PopFindCorpChrg("ST");

        // fn_PopFindCorpChrg(fr_SecuGrpId);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF37704.btn_IsuCdSearch_onclick" });
    }
};

/**
 * @method
 * @name dts_List_OnLoadError
 * @description dts_List 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_List_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_List);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF37704.dts_List_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_List_OnLoadCompleted
 * @description dts_List 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    try {
        $c.stf.fillGridHeaderTotalCnt(rowcount, panel_page);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF37704.dts_List_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name img_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_Close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF37704.img_Close_onclick" });
    }
};

/**
 * @method
 * @name grd_List_OnDblClick
 * @description grd_List 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.grd_List_OnDblClick = function(row, colid) {

};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name search
 * @description search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function() {
    const sbmOptions = {
        id : "sbm_dts_List",
        action : "/administrativeIssue.do",
        ref : "",
        target : "dts_List=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name getParIsur
 * @description dialog 호출용 함수 예비심사청구제출기관 호출관련
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.getParIsur = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    arrPar[0] = txb_IsurCd.getValue(); // 코드값을 포함할 컨트롤
    arrPar[1] = txb_IsurNm.getValue(); // 명칭값을 포함할 컨트롤
    arrPar[2] = "ST"; // 명칭값을 포함할 컨트롤

    return arrPar.length;
};

/**
 * @method
 * @name setParIsur
 * @description set Par Isur 처리
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setParIsur = async function(arrPar) {
    txb_IsurCd.setValue(arrPar[0].ISUR_CD);
    txb_IsurNm.setValue(arrPar[0].COM_NM);
    await scwin.search();
};
